join public.subcategories s on s.category_id = c.id and s.slug = v.subcategory_slug;

-- ---- verify before committing: any failure raises and rolls EVERYTHING back --------
do $$
declare
  n_cat int; n_sub int; n_prod int; n_pkg int; n_unavail text; seq_last bigint; seq_called boolean;
begin
  select count(*) into n_cat  from public.categories;
  select count(*) into n_sub  from public.subcategories;
  select count(*) into n_prod from public.products;
  if n_cat <> 2 or n_sub <> 32 or n_prod <> 141 then
    raise exception 'seed check failed: expected 2/32/141 categories/subcategories/products, got %/%/%', n_cat, n_sub, n_prod;
  end if;
  if (select count(*) from public.products p join public.categories c on c.id = p.category_id where c.slug = 'cigarettes') <> 110 then
    raise exception 'seed check failed: category cigarettes should have 110 products';
  end if;
  if (select count(*) from public.products p join public.categories c on c.id = p.category_id where c.slug = 'tobacco') <> 31 then
    raise exception 'seed check failed: category tobacco should have 31 products';
  end if;
  if exists (select 1 from public.products where subcategory_id is null) then
    raise exception 'seed check failed: a product has no subcategory';
  end if;
  select count(*) into n_pkg from public.products
   where package_enabled and package_sale_enabled and package_label = 'פקט' and package_unit_count = 10
     and package_price = unit_price * 10 and package_sale_price = package_price - 10
     and not unit_sale_enabled;
  if n_pkg <> 141 then
    raise exception 'seed check failed: package/sale values wrong on % rows', 141 - n_pkg;
  end if;
  select string_agg(id, ',' order by id::int) into n_unavail from public.products where not unit_available or not package_available;
  if n_unavail is distinct from '3,9' then
    raise exception 'seed check failed: unavailable products are %, expected 3,9', n_unavail;
  end if;
  select last_value, is_called into seq_last, seq_called from public.product_id_seq;
  if seq_last <> 149 or seq_called then
    raise exception 'seed check failed: product_id_seq was consumed (last_value %, is_called %)', seq_last, seq_called;
  end if;
end
$$;

commit;
